preConditionHook:
// Entry & Exit Confessions E25 "Classic Bollinger Bands", verbatim --
// deliberately NOT split: the band cross AND the length2-bar momentum
// confirmation, as the book's code has them (its plain-English text
// omits the momentum term). Equals BollingerBandCross + Momentum(length2).
// EEC E25's bands: BollingerBand(close, length, +/-numDevs) = Average(close,
// length) + NumDevs x StdDev with the POPULATION deviation (divide by N),
// recomputed FRESH every bar over the window INCLUDING the current bar, and
// summed NEWEST-FIRST (bar [0] added first -- EL's Summation order): the
// oldest-first order drifts in the last bit, so do not reorder these loops.
// All measured -- the `bollingerband` register row.
bbAvg = 0.0;
for (int i = 0; i < (int)length; ++i) {
    bbAvg += close[i];
}
bbAvg /= (int)length;
bbSd = 0.0;
for (int i = 0; i < (int)length; ++i) {
    double d = close[i] - bbAvg;
    bbSd += d * d;
}
bbSd = std::sqrt(bbSd / (int)length);
// The twin calls BollingerBand(close, length, -numDevs): avg + (-K) x sd.
// a + (-b)*c and a - b*c are bit-identical in IEEE (negation is exact).
lowerBand = bbAvg + (-numDevs) * bbSd;
upperBand = bbAvg + numDevs * bbSd;
// EL's `crosses` is a STATE MACHINE, not a two-bar test (the `crosses over` /
// `crosses under` register row, VERIFIED): it fires when the toleranced
// comparison holds AND the most recent NON-equal bar was on the other side.
// An equality run (el_eq, absolute 2.22e-12) is BRIDGED -- above -> equal ->
// above does NOT re-fire -- and the side starts UNKNOWN (0) at the first
// evaluated bar, so nothing can fire on bar 1. The book assigns the bands to
// EL variables, but they are recomputed from price every bar, so the cross
// state is modelled on the computed band values.
crossUpLower = el_gt(close[0], lowerBand) && lastSideLower == -1;
crossDownUpper = el_lt(close[0], upperBand) && lastSideUpper == 1;
// Update the sides AFTER the fire flags; an el_eq bar leaves them unchanged.
if (el_gt(close[0], lowerBand)) { lastSideLower = 1; }
else if (el_lt(close[0], lowerBand)) { lastSideLower = -1; }
if (el_gt(close[0], upperBand)) { lastSideUpper = 1; }
else if (el_lt(close[0], upperBand)) { lastSideUpper = -1; }
